from google.cloud import translate

def get_translate_client():
    """Returns a Google Cloud Translation client."""
    return translate.TranslationServiceClient()

class TranslationRequest:
    def __init__(self, text, target_language, source_language=None):
        self.text = text
        self.target_language = target_language
        self.source_language = source_language

class TranslationResponse:
    def __init__(self, translated_text, detected_source_language=None):
        self.translated_text = translated_text
        self.detected_source_language = detected_source_language

from translation_client import get_translate_client
from translation_models import TranslationRequest, TranslationResponse

def translate_text(request: TranslationRequest) -> TranslationResponse:
    client = get_translate_client()
    parent = f"projects/{{YOUR_PROJECT_ID}}/locations/global"

    if request.source_language:
        response = client.translate_text(
            request= {
                "parent": parent,
                "contents": [request.text],
                "target_language_code": request.target_language,
                "source_language_code": request.source_language,
            }
        )
    else:
        response = client.translate_text(
            request= {
                "parent": parent,
                "contents": [request.text],
                "target_language_code": request.target_language,
            }
        )

    translated_text = response.translations[0].translated_text
    detected_source_language = response.translations[0].detected_language_code
    return TranslationResponse(translated_text, detected_source_language)

